//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXWorkbook.
package xlsx
import("archive/zip";"bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"strings";"testing")
func TestCodexXLSXWorkbook(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","form-fixed.xlsx","form-pages.xlsx","form-rows.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(148628));for i:=0;i<800;i++ {var b bytes.Buffer;z:=zip.NewWriter(&b);add:=func(name,content string){f,e:=z.Create(name);if e!=nil{t.Fatal(e)};f.Write([]byte(content))};wbPart:="xl/workbook.xml";if i%4==0 {wbPart="custom/book.xml";add("_rels/.rels",`<Relationships><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="custom/book.xml"/></Relationships>`)};dir:=filepath.ToSlash(filepath.Dir(wbPart));base:=filepath.Base(wbPart);relfile:=dir+"/_rels/"+base+".rels";xml:=`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">`;if i%3==0{xml+=`<workbookPr date1904="`+[]string{"1","0","true","false","on","off"}[r.Intn(6)]+`"/>`};if i%6==0{xml+=`<workbookPr date1904="true"/>`};xml+="<sheets>";rel:=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">`;for j:=0;j<r.Intn(9);j++ {id:=fmt.Sprintf("rId%d",j+1);name:=fmt.Sprintf("Sheet %d-%d",i,j);state:=[]string{"visible","hidden","veryHidden","unknown"}[r.Intn(4)];xml+=fmt.Sprintf(`<sheet name="%s" state="%s" sheetId="%d" r:id="%s"/>`,name,state,j+1,id);if j%7!=0{kind:=[]string{"worksheet","chartsheet","dialogsheet","macrosheet"}[r.Intn(4)];rel+=fmt.Sprintf(`<Relationship Id="%s" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/%s" Target="worksheets/sheet%d.xml"/>`,id,kind,j+1)}};xml+="</sheets></workbook>";rel+="</Relationships>";add(wbPart,xml);add(relfile,rel);if e:=z.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};out:=[]any{};for _,data:=range samples{c,_,e:=openWorkbook(bytes.NewReader(data),int64(len(data)),&Options{NoSystemFonts:true,SystemFonts:true});if e!=nil{t.Fatal(e)};sheets:=[]any{};for _,v:=range c.sheets{sheets=append(sheets,[]any{v.name,v.part,v.chart,v.hidden,v.idx})};warnings:=[]string{};for _,w:=range c.warnings{if strings.HasPrefix(w,"sheet "){warnings=append(warnings,w)}};out=append(out,map[string]any{"input":data,"want":[]any{c.wbPart,c.date1904,sheets,warnings}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/workbook.json"),b,0644);e!=nil{t.Fatal(e)}}
